values(9,'speaking','Full Speaking · Day 09','published',$payload${"version":"speaking-day-9-v1","part1":{"topic":"TOPIC 12. SHOPPING","questions":[{"key":"p1_q1","text":"Do you like shopping?"},{"key":"p1_q2","text":"How often do you go shopping?"},{"key":"p1_q3","text":"Do you compare prices when you shop?"},{"key":"p1_q4","text":"Is it difficult for you to make choices when you shop?"}]},"part2":{"topic":"TOPIC 11. PLACE YOU'VE TRAVELLED TO THAT YOU'D LIKE TO RECOMMEND TO OTHERS","key":"p2_main","prompt":"Describe a place you've travelled to that you'd recommend to others.","bullets":["what place it was","why you went there","what you did there","how you felt about it"],"preparation_seconds":60,"max_answer_seconds":120},"part3":{"topic":"TOPIC 11. HOLIDAYS","questions":[{"key":"p3_q1","text":"What do you need to do before you travel?"},{"key":"p3_q2","text":"What preparations should people make before going on holiday?"},{"key":"p3_q3","text":"Where do people usually travel on holidays?"},{"key":"p3_q4","text":"Do you think it's important to do some preparation before you travel to new places?"}]}}$payload$::jsonb,now(),now())
